from math import factorial
from functools import lru_cache

@lru_cache(maxsize=None)
def catalan(n):
    if n == 0:
        return 1
    return sum(catalan(i) * catalan(n-i-1) for i in range(n))

def subsequenceCount(base_s, target_s, len_n):
    base_len = len(base_s)
    total_parts = (base_len - len_n + 1) ** len_n
    unique_parts = factorial(base_len) // (factorial(base_len - len_n) * factorial(len_n))
    c = catalan(base_len - len_n)
    return (total_parts * unique_parts // c) % (10**9 + 7) if target_s in base_s else 0

