def is_good_string(s, K, mod=10**9 + 7):
    n = len(s)
    good_strings = 0
    alphabet_size = 3 
    dp = [[[0 for _ in range(n + 1)] for _ in range(alphabet_size)] for _ in range(K + 1)]

    for i in range(alphabet_size):
        for j in range(n + 1):
            dp[0][i][j] = 1

    for k in range(1, K + 1):
        for a in range(alphabet_size):
            for b in range(alphabet_size):
                if s[0] == chr(a + ord('a')) and a != b:
                    dp[k][b][1] = ((dp[k][a][1] + dp[k][b][1]) % mod)
                for i in range(1, n):
                    dp[k][a][i] = ((dp[k][a][i] + (dp[k - 1][b][i - 1] + mod_pow(alphabet_size, i - 1)) % mod) % mod)
                    dp[k][b][i] = ((dp[k][b][i] + dp[k][a][i - 1] - (dp[k][a][i - 1] + dp[k][b][i - 1]) % mod + mod) % mod)

    good_strings = dp[K][lambda c: ord('a')][n]

    return good_strings

