import sys

def max_breadth(n: int, l: int, r: int, heights: list, important: list):
    """
    Calculate the maximum convenience of a wardrobe maximally over a list of boxes.
    """
    dp = [0] * (r+1)
    memo = {}

    def dp_calhelper(i, prev, prev_importance):
        if i >= n:
            return 0
        if (i, prev, prev_importance) not in memo:
            memo[(i, prev, prev_importance)] = dp_calhelper(i+1, prev, prev_importance)
        max_number = 0
        if prev_importance == important[i]:
            max_number = -1
        dp_calhelper.execute_location(dp, heights[i] - prev, max_number, important[i], i+1, prev, prev_importance)
        memo[(i, prev, prev_importance)] += max_number
        return memo[(i, prev, prev_importance)]

    def dp_calhelper.execute_location(dp, val, max_number, important, i, prev, prev_importance):
        if i == n:
            if max_number > 0:
                dp[val] = max_number
            return
        if val > dp[(i+1), prev, prev_importance]:
            dp_calhelper.execute_location(dp, heights[i] - prev, max_number, important, i+1, heights[i], important[i])
        else:
            return
        dp_calhelper.execute_location(dp, heights[i] - prev, max_number, important, i+1, prev, prev_importance)

    return dp

