def num_leafs(node, graph, level=0):
    if node not in graph:
        return level - bfs(node, graph)

    if len(graph[node]) == 1:
        # Leaf node
        return 1

    # Non-leaf node with one child
    for child in graph[node]:
        result = num_leafs(child, graph, level + 1)
        return result * (1 if child == node else -1)

