from math import gcd
from itertools import combinations
from functools import reduce

def gcd_list(numbers):
    return reduce(gcd, numbers)

def smallest_insertions(N, sequence):
    dp = [float('inf')] * (N-1)
    adp = [float('inf')] * (N-1)
    for possible_subseq in combinations(range(N), N-1):
        start, end = possible_subseq[:len(possible_subseq)//2], possible_subseq[len(possible_subseq)//2:]
        gcd_values = [gcd_list(map(sequence[x-1], end)) for x in start]
        best_value = 0
        for i in range(len(start)):
            for j in range(i+1, len(start)+1):
                if j-i <= N-1:
                    best_value = min(best_value, max(gcd_values[:j-i])**2 + ((j-i)-len(set(gcd_values[:j-i]))))
                else:
                    break
        dp[0] = best_value
    for i in range(1, len(dp)):
        adp[i-1] = min(dp[i-1], adp[i-2])
    return list(reversed(adp))

for _ in range(int(input())):
    N = int(input())
    sequence = list(map(int, input().split()))
    result = smallest_insertions(N, sequence)
