def min_delete_count(binary_str, forbidden_sequences):
    n = len(binary_str)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if binary_str[i-1:j] not in forbidden_sequences:
                dp[i][j] = 0
            else:
                possible = []  # Store all positions where the forbidden sequence starts
                start, end = -1, -1
                match = False
                match_start = [-1, n]

                for k in range(i, j + 1):
                    if binary_str[k] == '0' and start == -1:
                        start = k
                    if binary_str[k] == '1' and end == -1:
                        end = k

                    if start != -1 and end != -1 and match == False:
                        possible = [i for i, seq in enumerate(forbidden_sequences) if i in range(start, end + 1)]
                        match = True  # Set match to True
                        match_start = list(sorted(possible, key=lambda x: x-start))

                    if start != -1 and start < k-1 and binary_str[k] == '1' and end == -1:
                        end = k
                        break

                if not possible:
                    dp[i][j] = n
                elif len(possible) == 2:  # Abort sequence of length 2, starting from a value which shall be checked
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[match_start[0]][match_start[1]+1]+1, dp[match_start[1]][j]+1)

    return dp[1][n]


