def min_swaps_to_remove_substrings(substrings, n):
    @lru_cache(maxsize=None)
    def dp(index, last, prev):
        if index >= n:
            return 0
        swaps = float('inf')
        for i in range(last + 1, min(n, index + 2)):
            if substrings[index][i] != 'K' and substrings[index][i] != 'V':
                swaps = min(swaps, dp(index + 1, i, substrings[index][i]))
        return 1 + swaps

    min_swaps = float('inf')
    for i, c in enumerate(substrings):
        if c == 'V' or c == 'K':
            continue
        min_swaps = min(min_swaps, dp(0, i, c))
    return min_swaps

