from math import log2

def count_subsequences(known_words, n, s):
    length = len(s)
    mod = 10**9 + 7

    # Calculate the number of subsequence starting with s[0]
    if known_words[s[0]]:
        mod = known_words[s[0]]
    else:
        for i in range(1, int(max(log2(length), log2(len(s)))) + 1):
            new_subseq = s[0:i] + s[i:]
            if new_subseq in known_words:
                mod += known_words[new_subseq]

        known_words[s[0]] = mod
    for i in range(1, length):
        if s[i - 1] in known_words:
            mod = mod * (length - i + 1) % mod
        if s[i] in known_words:
            mod = mod * (length - i) % mod

    mod *= 26 ** (n - length)
    mod = mod % mod
    return mod % mod

