def calculate_good_strings(A, s, K):
    count = 0
    n = len(s)
    alphabet_size = 1 << A
    for bitmask in range(alphabet_size):
        word = s[:n]
        for pos in range(n):
            if pos & bitmask:
                word[n:] = chr(ord(word[pos-1]) - 1 + (ord(word[pos]) - ord(word[pos-1]) - 1 + K) % MOD)
        if word[0] == word[-1] and is_good_string(word, K, A):
            count += 1
    return count % MOD

