import heapq

def dijkstra(G, s):
    n = len(G)

    # Initialize distances
    dist = [float('inf')] * n
    dist[s] = 0

    # Priority queue for nodes to visit
    pq = [(0, s)]

    while pq:
        (d, u) = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in G[u]:
            alt = d + w
            if alt < dist[v]:
                dist[v] = alt
                heapq.heappush(pq, (alt, v))

    return [min(dist[u], dist[v]) for u in range(n) for v in range(u + 1, n)]

def solve(n, m, G, a, b):
    dp, ans = [[inf] * (t + 1) for _ in range(n)], []
    for t in range(m):
        tmod = t % (1000 - 50)
        last, second_last, second_last_day = None, None, -1
        for i in range(n):
            for j, w in G[i].items():
                if i == j:
                    continue
                dp[j][t + 1], second_last, last = max(dp[i][tmod], dp[j][tmod]), dp[i][tmod], i
                if tmod == 0:
                    ans += [inf if i in second_last and j in last else last - i]
        for k in range(n):
            for l, c, f in (second_last, last, second_last_day, -1):
