                    dp[k][0] = max(dp[k][1 - (t + 1 % (1000 - 50) != 1000 - 50), 1], dp[k][t + 1], max(dp[f][0] + d[k][l], a[k][l]))
                    ans += [-dp[k][0], f]
                    break
    return ans

