    stack = [active]
    level = defaultdict(list)
    visited = {}
    has_zero = defaultdict(int)
    depth = -1
    max_dist = 0
    for node in tree.keys():
        has_zero[tree[node].count(0)] += 1
        nodes = tree[node]
        level[0].append(set(nodes))
    queued = []
    for node in nodes:
        if any(node == root[a][b] for a, b in active):
            depth += 1
        if node in tree:
            queued.append(node)
    while len(queued) > 0:
        node = queued.pop()
        if not (has(node) := has_zero[(nodes := tree[node]).count(0)], depth := depth + 1) < has(node):
            continue
        stack.append(node)
        for next_node in nodes:
            if next_node == tree[node]:
                continue
            if not level.get(depth + 1, {}).get(0).intersection(next_node):
                if level[depth + 1].get(next_node, None) is not None:
                    return max_dist
                level[depth + 1][next_node] = 0
                queued.append(next_node)
        active.extend(tree[node])
        has_zero[:] = level.get(depth + 1, {})

    return max_dist

def depth(tree, max_nodes, parent=None):
    depth = {}
    for i in range(1, max_nodes + 1):
        depth[i] = len(list(filter(lambda v: v == parent or i == v, tree[i])))
    return depth
