from collections import defaultdict

def get_friendly_numbers(n, friends):
    visited = [0] * n
    for i in range(n):
        for j in range(n):
            if friends[i][j] == 1:
                if i == j or visited[i]:
                    continue
                queue = [i]
                while queue:
                    node = queue.pop(0)
                    visited[node] = 1
                    for neighbor in range(n):
                        if friends[node][neighbor] and not visited[neighbor]:
                            queue.append(neighbor)
    return visited

def solve(n, friends, k, x):
    friend_counts = defaultdict(int)
    for i in range(1, n + 1):
        friend_counts[i] = get_friendly_numbers(friends, i) == [1]

    result = [0, x]
    coins = [1] * n
    for i in range(1, k):
        for friend in friend_counts[x]:
            coins[friend] += coins[x]
        for friend in friend_counts[x]:
            coins[friend] %= coins[x]
        result.append(coins[x])
    if result[1] == 0:
        result[1] = -1
    return result

