from collections import deque

def findMinimumMoves(s):
    queue = deque([(0, 0, 0)])  # (previous index, number of swaps, violations of "VK")
    processed = set()
    while queue:
        prev, moves, violations = queue.popleft()
        if violations >= len(s):
            continue
        s_prev = s[prev:]
        s_next = s[prev+1:]
        if prev > 0 and "VK" in s_prev:
            queue.append((prev - 2, moves + 1, violations))  # Move VK to s_prev[-2]
        if prev > 1 and "VK" in s_next:
            queue.append((prev - 2, moves + 1, violations))  # Move VK to s_next[-2]
        if prev < len(s)-1 and "VK" in s_next:
            queue.append((prev + 2, moves + 1, violations))  # Move VK to s_next[1]
        if prev == 0 and "VK" in s_next:
            queue.append((prev + 2, moves + 1, violations))  # Move VK to s_next[1]
        if prev == len(s)-1 and "VK" in s_next:
            queue.append((prev + 2, moves + 1, violations))  # Move VK to s_next[1]
        if prev == 0 and s_next == "VK":
            queue.appendleft((prev - 2, moves + 1, violations))  # Move VK to s_prev[-2]
        if prev == len(s)-1 and s_next == "VK":
            queue.appendleft((prev - 2, moves + 1, violations))  # Move VK to s_prev[-2]
        if (prev, violations) not in processed:
            processed.add((prev, violations))
            queue.extend([(prev + x, moves, violations + 1) for x in range(3)])
        if violations < len(s):
            queue.append((prev, moves, violations))
            processed.add((prev, violations))

    return moves

