def min_deletions_to_pure(binary_string):
    """
    Finds the minimum number of deletions required to make the binary string pure.

    :param binary_string: A binary string (string containing only '0' and '1').
    :return: The minimum number of deletions required to make the string pure.
    """
    dp = [0] * len(binary_string)
    for i in range(len(binary_string)):
        dp[i] = i + 1
        for j in range(i):
            if binary_string[i] == '0' and binary_string[j] == '1':
                dp[i] = min(dp[i], dp[j] + 1)
            elif binary_string[i] == '1' and binary_string[j] == '0':
                dp[i] = min(dp[i], dp[j] + 1)
    return min(dp)

